"""Karnataka PUC practicals added to close the practical map: Na2CO3/HCl
titration, pH and dilution, meiosis slides, pollination adaptations and DNA
isolation. Written for KINETIX; reviewed=False until a teacher checks them."""


def add(lab, W, Q):
    chem1 = dict(subject='Chemistry', domain='chemistry', levels=[11], curricula=['ka-puc', 'cbse', 'ncert'])
    bio2 = dict(subject='Biology', domain='biology', levels=[12], curricula=['ka-puc', 'cbse', 'ncert'])
    GOGGLES = W('Wear safety goggles; acids and alkalis harm the eyes.', 'सुरक्षा चश्मा पहनें; अम्ल और क्षार आँखों को हानि पहुँचाते हैं।', 'ಸುರಕ್ಷಾ ಕನ್ನಡಕ ಧರಿಸಿ; ಆಮ್ಲ ಮತ್ತು ಕ್ಷಾರಗಳು ಕಣ್ಣಿಗೆ ಹಾನಿ ಮಾಡುತ್ತವೆ.')
    RECORD = W('Record book and pencil', 'अभिलेख पुस्तिका और पेंसिल', 'ದಾಖಲೆ ಪುಸ್ತಕ ಮತ್ತು ಪೆನ್ಸಿಲ್')

    lab(id='titration-na2co3-hcl', bench='titration', setup={'pair': 'na2co3-hcl', 'indicator': 'methyl-orange'}, **chem1,
        keywords=['titration', 'volumetric analysis', 'sodium carbonate', 'hydrochloric acid', 'methyl orange', 'primary standard', 'molarity'],
        title=W('Strength of HCl with standard sodium carbonate', 'मानक सोडियम कार्बोनेट से HCl की प्रबलता', 'ಪ್ರಮಾಣಿತ ಸೋಡಿಯಂ ಕಾರ್ಬೊನೇಟ್‌ನಿಂದ HCl ನ ಪ್ರಬಲತೆ'),
        summary=W('Titrate hydrochloric acid against 0.05 M sodium carbonate with methyl orange and find its molarity.', 'मेथिल ऑरेंज के साथ हाइड्रोक्लोरिक अम्ल का 0.05 M सोडियम कार्बोनेट से अनुमापन कर उसकी मोलरता ज्ञात करें।', 'ಮೀಥೈಲ್ ಆರೆಂಜ್ ಬಳಸಿ ಹೈಡ್ರೋಕ್ಲೋರಿಕ್ ಆಮ್ಲವನ್ನು 0.05 M ಸೋಡಿಯಂ ಕಾರ್ಬೊನೇಟ್ ವಿರುದ್ಧ ಅನುಮಾಪನ ಮಾಡಿ ಅದರ ಮೋಲಾರಿಟಿ ಕಂಡುಹಿಡಿಯಿರಿ.'),
        aim=W('To prepare a standard solution of sodium carbonate and use it to find the molarity of a given hydrochloric acid.', 'सोडियम कार्बोनेट का मानक विलयन बनाकर उससे दिए गए हाइड्रोक्लोरिक अम्ल की मोलरता ज्ञात करना।', 'ಸೋಡಿಯಂ ಕಾರ್ಬೊನೇಟ್‌ನ ಪ್ರಮಾಣಿತ ದ್ರಾವಣ ತಯಾರಿಸಿ ಅದರಿಂದ ಕೊಟ್ಟ ಹೈಡ್ರೋಕ್ಲೋರಿಕ್ ಆಮ್ಲದ ಮೋಲಾರಿಟಿ ಕಂಡುಹಿಡಿಯುವುದು.'),
        principle=W('Anhydrous Na₂CO₃ is a primary standard. Na₂CO₃ + 2HCl → 2NaCl + H₂O + CO₂. Methyl orange turns from yellow to orange at the end point (pH about 4). Moles of HCl = 2 × moles of Na₂CO₃, so M(HCl) = 2 × 0.05 × 10 ÷ titre.', 'निर्जल Na₂CO₃ प्राथमिक मानक है। Na₂CO₃ + 2HCl → 2NaCl + H₂O + CO₂. अंतिम बिंदु (pH लगभग 4) पर मेथिल ऑरेंज पीले से नारंगी हो जाता है। HCl के मोल = 2 × Na₂CO₃ के मोल, अतः M(HCl) = 2 × 0.05 × 10 ÷ अनुमापांक।', 'ನಿರ್ಜಲ Na₂CO₃ ಪ್ರಾಥಮಿಕ ಮಾನಕ. Na₂CO₃ + 2HCl → 2NaCl + H₂O + CO₂. ಅಂತ್ಯ ಬಿಂದುವಿನಲ್ಲಿ (pH ಸುಮಾರು 4) ಮೀಥೈಲ್ ಆರೆಂಜ್ ಹಳದಿಯಿಂದ ಕಿತ್ತಳೆಯಾಗುತ್ತದೆ. HCl ಮೋಲ್ = 2 × Na₂CO₃ ಮೋಲ್; ಆದ್ದರಿಂದ M(HCl) = 2 × 0.05 × 10 ÷ ಅನುಮಾಪನಾಂಕ.'),
        apparatus=[W('Burette (50 mL) with stand', 'स्टैंड सहित ब्यूरेट (50 mL)', 'ಸ್ಟ್ಯಾಂಡ್ ಸಹಿತ ಬ್ಯೂರೆಟ್ (50 mL)'), W('Pipette (10 mL) and conical flask', 'पिपेट (10 mL) और शंक्वाकार फ्लास्क', 'ಪಿಪೆಟ್ (10 mL) ಮತ್ತು ಶಂಕುವಿನಾಕಾರದ ಫ್ಲಾಸ್ಕ್'), W('250 mL measuring flask and weighing bottle', '250 mL मापक फ्लास्क और तौल बोतल', '250 mL ಅಳತೆ ಫ್ಲಾಸ್ಕ್ ಮತ್ತು ತೂಕದ ಬಾಟಲಿ'), W('Anhydrous sodium carbonate and methyl orange', 'निर्जल सोडियम कार्बोनेट और मेथिल ऑरेंज', 'ನಿರ್ಜಲ ಸೋಡಿಯಂ ಕಾರ್ಬೊನೇಟ್ ಮತ್ತು ಮೀಥೈಲ್ ಆರೆಂಜ್')],
        steps=[W('Weigh 1.325 g of anhydrous Na₂CO₃, dissolve it and make up to 250 mL: a 0.05 M solution.', '1.325 g निर्जल Na₂CO₃ तौलें, घोलें और 250 mL तक बनाएँ: 0.05 M विलयन।', '1.325 g ನಿರ್ಜಲ Na₂CO₃ ತೂಗಿ, ಕರಗಿಸಿ 250 mL ಮಾಡಿ: 0.05 M ದ್ರಾವಣ.'),
               W('Fill the burette with the hydrochloric acid and note the initial reading.', 'ब्यूरेट में हाइड्रोक्लोरिक अम्ल भरें और प्रारंभिक पाठ्यांक लिखें।', 'ಬ್ಯೂರೆಟ್‌ಗೆ ಹೈಡ್ರೋಕ್ಲೋರಿಕ್ ಆಮ್ಲ ತುಂಬಿ ಆರಂಭಿಕ ಓದು ಬರೆಯಿರಿ.'),
               W('Pipette 10 mL of the carbonate into the flask and add two drops of methyl orange.', 'फ्लास्क में 10 mL कार्बोनेट पिपेट से लें और मेथिल ऑरेंज की दो बूँदें डालें।', 'ಫ್ಲಾಸ್ಕ್‌ಗೆ 10 mL ಕಾರ್ಬೊನೇಟ್ ಪಿಪೆಟ್‌ನಿಂದ ಹಾಕಿ ಎರಡು ಹನಿ ಮೀಥೈಲ್ ಆರೆಂಜ್ ಸೇರಿಸಿ.'),
               W('Run in the acid, swirling, until the yellow just turns orange. Record the final reading.', 'घुमाते हुए अम्ल डालें जब तक पीला रंग ठीक नारंगी न हो जाए। अंतिम पाठ्यांक लिखें।', 'ತಿರುಗಿಸುತ್ತಾ ಆಮ್ಲ ಸೇರಿಸಿ, ಹಳದಿ ಕಿತ್ತಳೆಯಾಗುವವರೆಗೆ. ಅಂತಿಮ ಓದು ದಾಖಲಿಸಿ.'),
               W('Repeat for concordant readings and work out the molarity of the acid.', 'सहमत पाठ्यांकों के लिए दोहराएँ और अम्ल की मोलरता निकालें।', 'ಹೊಂದಿಕೆಯ ಓದುಗಳಿಗಾಗಿ ಪುನರಾವರ್ತಿಸಿ ಆಮ್ಲದ ಮೋಲಾರಿಟಿ ಲೆಕ್ಕಹಾಕಿ.')],
        precautions=[W('Near the end point add the acid drop by drop, swirling the flask.', 'अंतिम बिंदु के पास अम्ल बूँद-बूँद डालें और फ्लास्क घुमाते रहें।', 'ಅಂತ್ಯ ಬಿಂದುವಿನ ಹತ್ತಿರ ಆಮ್ಲವನ್ನು ಹನಿ ಹನಿಯಾಗಿ ಸೇರಿಸಿ, ಫ್ಲಾಸ್ಕ್ ತಿರುಗಿಸಿ.'), W('Use only two drops of indicator; read the lower meniscus at eye level.', 'सूचक की केवल दो बूँदें डालें; निचला नवचंद्रक आँख के स्तर पर पढ़ें।', 'ಸೂಚಕದ ಎರಡೇ ಹನಿ ಬಳಸಿ; ಕೆಳಗಿನ ಮೆನಿಸ್ಕಸನ್ನು ಕಣ್ಣಿನ ಮಟ್ಟದಲ್ಲಿ ಓದಿ.'), GOGGLES],
        conclusion=W('Concordant titres to the methyl orange end point give the molarity of the hydrochloric acid.', 'मेथिल ऑरेंज अंतिम बिंदु तक के सहमत अनुमापांक हाइड्रोक्लोरिक अम्ल की मोलरता देते हैं।', 'ಮೀಥೈಲ್ ಆರೆಂಜ್ ಅಂತ್ಯ ಬಿಂದುವಿನವರೆಗಿನ ಹೊಂದಿಕೆಯ ಅನುಮಾಪನಾಂಕಗಳು ಹೈಡ್ರೋಕ್ಲೋರಿಕ್ ಆಮ್ಲದ ಮೋಲಾರಿಟಿ ನೀಡುತ್ತವೆ.'),
        viva=[Q(W('Why is methyl orange used here and not phenolphthalein?', 'यहाँ फ़िनॉल्फ़्थेलिन के स्थान पर मेथिल ऑरेंज क्यों?', 'ಇಲ್ಲಿ ಫೀನಾಲ್ಫ್ತಲೀನ್ ಬದಲು ಮೀಥೈಲ್ ಆರೆಂಜ್ ಏಕೆ?'), W('Phenolphthalein changes when carbonate has only become hydrogencarbonate; the full reaction ends near pH 4, where methyl orange changes.', 'फ़िनॉल्फ़्थेलिन तभी बदलता है जब कार्बोनेट केवल हाइड्रोजनकार्बोनेट बना हो; पूरी अभिक्रिया pH 4 के पास पूरी होती है, जहाँ मेथिल ऑरेंज बदलता है।', 'ಕಾರ್ಬೊನೇಟ್ ಹೈಡ್ರೋಜನ್‌ಕಾರ್ಬೊನೇಟ್ ಆದಾಗಲೇ ಫೀನಾಲ್ಫ್ತಲೀನ್ ಬದಲಾಗುತ್ತದೆ; ಪೂರ್ಣ ಕ್ರಿಯೆ pH 4 ಹತ್ತಿರ ಮುಗಿಯುತ್ತದೆ, ಅಲ್ಲಿ ಮೀಥೈಲ್ ಆರೆಂಜ್ ಬದಲಾಗುತ್ತದೆ.')),
              Q(W('Why is anhydrous sodium carbonate a primary standard?', 'निर्जल सोडियम कार्बोनेट प्राथमिक मानक क्यों है?', 'ನಿರ್ಜಲ ಸೋಡಿಯಂ ಕಾರ್ಬೊನೇಟ್ ಪ್ರಾಥಮಿಕ ಮಾನಕ ಏಕೆ?'), W('It is pure, stable and does not absorb moisture or CO₂, so it can be weighed exactly.', 'यह शुद्ध, स्थिर है और नमी या CO₂ नहीं सोखता, इसलिए सटीक तौला जा सकता है।', 'ಅದು ಶುದ್ಧ, ಸ್ಥಿರ; ತೇವಾಂಶ ಅಥವಾ CO₂ ಹೀರುವುದಿಲ್ಲ, ಆದ್ದರಿಂದ ನಿಖರವಾಗಿ ತೂಗಬಹುದು.')),
              Q(W('What is the molar mass of Na₂CO₃?', 'Na₂CO₃ का मोलर द्रव्यमान क्या है?', 'Na₂CO₃ ನ ಮೋಲಾರ್ ದ್ರವ್ಯರಾಶಿ ಎಷ್ಟು?'), W('106 g/mol.', '106 g/mol (ग्राम प्रति मोल)।', '106 g/mol (ಗ್ರಾಂ ಪ್ರತಿ ಮೋಲ್).'))])

    lab(id='ph-of-solutions', bench='indicators', setup={'indicator': 'universal', 'sample': 'hcl', 'dilution': 1.0}, **chem1,
        keywords=['ph', 'universal indicator', 'dilution', 'acids', 'bases', 'equilibrium', 'ionic equilibrium', 'strong acid', 'weak acid'],
        title=W('pH of solutions and the effect of dilution', 'विलयनों का pH और तनुकरण का प्रभाव', 'ದ್ರಾವಣಗಳ pH ಮತ್ತು ದುರ್ಬಲೀಕರಣದ ಪರಿಣಾಮ'),
        summary=W('Find the pH of acids, bases and salts with universal indicator and see how dilution changes it.', 'सार्वत्रिक सूचक से अम्लों, क्षारों और लवणों का pH ज्ञात करें और देखें कि तनुकरण उसे कैसे बदलता है।', 'ಸಾರ್ವತ್ರಿಕ ಸೂಚಕದಿಂದ ಆಮ್ಲ, ಕ್ಷಾರ ಮತ್ತು ಲವಣಗಳ pH ಕಂಡುಹಿಡಿದು ದುರ್ಬಲೀಕರಣ ಅದನ್ನು ಹೇಗೆ ಬದಲಿಸುತ್ತದೆ ನೋಡಿ.'),
        aim=W('To determine the pH of some solutions with universal indicator and to study the change in pH of an acid and a base on dilution.', 'सार्वत्रिक सूचक से कुछ विलयनों का pH ज्ञात करना और तनुकरण पर अम्ल व क्षार के pH में परिवर्तन का अध्ययन करना।', 'ಸಾರ್ವತ್ರಿಕ ಸೂಚಕದಿಂದ ಕೆಲವು ದ್ರಾವಣಗಳ pH ಕಂಡುಹಿಡಿಯುವುದು ಮತ್ತು ದುರ್ಬಲೀಕರಣದಿಂದ ಆಮ್ಲ ಹಾಗೂ ಕ್ಷಾರದ pH ಬದಲಾವಣೆ ಅಧ್ಯಯನ ಮಾಡುವುದು.'),
        principle=W('pH = −log[H⁺]. Diluting a strong acid tenfold lowers [H⁺] tenfold, so its pH rises by 1; a weak acid ionises more on dilution, so its pH rises by only about 0.5. On dilution pH moves towards 7 but never crosses it.', 'pH = −log[H⁺]. प्रबल अम्ल को दस गुना तनु करने पर [H⁺] दस गुना घटता है, अतः pH 1 बढ़ता है; दुर्बल अम्ल तनुकरण पर अधिक आयनित होता है, इसलिए pH केवल लगभग 0.5 बढ़ता है। तनुकरण पर pH 7 की ओर जाता है पर उसे पार नहीं करता।', 'pH = −log[H⁺]. ಪ್ರಬಲ ಆಮ್ಲವನ್ನು ಹತ್ತು ಪಟ್ಟು ದುರ್ಬಲಗೊಳಿಸಿದರೆ [H⁺] ಹತ್ತು ಪಟ್ಟು ಕಡಿಮೆ, pH 1 ಹೆಚ್ಚುತ್ತದೆ; ದುರ್ಬಲ ಆಮ್ಲ ದುರ್ಬಲೀಕರಣದಲ್ಲಿ ಹೆಚ್ಚು ಅಯಾನೀಕರಿಸುತ್ತದೆ, pH ಸುಮಾರು 0.5 ಮಾತ್ರ ಹೆಚ್ಚುತ್ತದೆ. pH 7 ಕಡೆಗೆ ಸಾಗುತ್ತದೆ, ಅದನ್ನು ದಾಟುವುದಿಲ್ಲ.'),
        apparatus=[W('Test tubes and stand', 'परखनलियाँ और स्टैंड', 'ಪರೀಕ್ಷಾ ನಳಿಕೆಗಳು ಮತ್ತು ಸ್ಟ್ಯಾಂಡ್'), W('Universal indicator and its colour chart', 'सार्वत्रिक सूचक और उसका रंग चार्ट', 'ಸಾರ್ವತ್ರಿಕ ಸೂಚಕ ಮತ್ತು ಅದರ ಬಣ್ಣ ಚಾರ್ಟ್'), W('Dilute HCl, acetic acid, NaOH and salt solutions', 'तनु HCl, ऐसीटिक अम्ल, NaOH और लवण विलयन', 'ದುರ್ಬಲ HCl, ಅಸಿಟಿಕ್ ಆಮ್ಲ, NaOH ಮತ್ತು ಲವಣ ದ್ರಾವಣಗಳು'), W('Measuring cylinder and distilled water', 'मापक सिलिंडर और आसुत जल', 'ಅಳತೆ ಸಿಲಿಂಡರ್ ಮತ್ತು ಬಟ್ಟಿ ನೀರು')],
        steps=[W('Take 5 mL of each solution in a clean test tube.', 'हर विलयन का 5 mL एक साफ़ परखनली में लें।', 'ಪ್ರತಿ ದ್ರಾವಣದ 5 mL ಅನ್ನು ಸ್ವಚ್ಛ ಪರೀಕ್ಷಾ ನಳಿಕೆಯಲ್ಲಿ ತೆಗೆದುಕೊಳ್ಳಿ.'),
               W('Add two drops of universal indicator and match the colour with the chart.', 'सार्वत्रिक सूचक की दो बूँदें डालें और रंग का चार्ट से मिलान करें।', 'ಎರಡು ಹನಿ ಸಾರ್ವತ್ರಿಕ ಸೂಚಕ ಸೇರಿಸಿ ಬಣ್ಣವನ್ನು ಚಾರ್ಟ್‌ನೊಂದಿಗೆ ಹೋಲಿಸಿ.'),
               W('Dilute the hydrochloric acid 1:10, 1:100 and 1:1000 and test each.', 'हाइड्रोक्लोरिक अम्ल को 1:10, 1:100 और 1:1000 तनु करें और हर एक जाँचें।', 'ಹೈಡ್ರೋಕ್ಲೋರಿಕ್ ಆಮ್ಲವನ್ನು 1:10, 1:100, 1:1000 ದುರ್ಬಲಗೊಳಿಸಿ ಪ್ರತಿಯೊಂದನ್ನೂ ಪರೀಕ್ಷಿಸಿ.'),
               W('Repeat with acetic acid (vinegar) and sodium hydroxide.', 'ऐसीटिक अम्ल (सिरका) और सोडियम हाइड्रॉक्साइड के साथ दोहराएँ।', 'ಅಸಿಟಿಕ್ ಆಮ್ಲ (ವಿನೆಗರ್) ಮತ್ತು ಸೋಡಿಯಂ ಹೈಡ್ರಾಕ್ಸೈಡ್‌ನೊಂದಿಗೆ ಪುನರಾವರ್ತಿಸಿ.'),
               W('Record each pH and compare how strong and weak electrolytes change.', 'हर pH दर्ज करें और प्रबल व दुर्बल विद्युत-अपघट्यों के परिवर्तन की तुलना करें।', 'ಪ್ರತಿ pH ದಾಖಲಿಸಿ, ಪ್ರಬಲ ಮತ್ತು ದುರ್ಬಲ ವಿದ್ಯುದ್ವಿಭಾಜ್ಯಗಳ ಬದಲಾವಣೆ ಹೋಲಿಸಿ.')],
        precautions=[W('Use clean tubes and the same number of indicator drops each time.', 'साफ़ परखनलियाँ और हर बार सूचक की उतनी ही बूँदें लें।', 'ಸ್ವಚ್ಛ ನಳಿಕೆಗಳು ಮತ್ತು ಪ್ರತಿ ಬಾರಿ ಅಷ್ಟೇ ಹನಿ ಸೂಚಕ ಬಳಸಿ.'), W('Compare colours against a white background in good light.', 'अच्छी रोशनी में सफ़ेद पृष्ठभूमि पर रंगों की तुलना करें।', 'ಉತ್ತಮ ಬೆಳಕಿನಲ್ಲಿ ಬಿಳಿ ಹಿನ್ನೆಲೆಯಲ್ಲಿ ಬಣ್ಣ ಹೋಲಿಸಿ.'), GOGGLES],
        conclusion=W('Each tenfold dilution raises the pH of a strong acid by one unit and of a weak acid by about half a unit; bases fall towards 7 the same way.', 'हर दस गुना तनुकरण प्रबल अम्ल का pH एक इकाई और दुर्बल अम्ल का लगभग आधी इकाई बढ़ाता है; क्षार इसी प्रकार 7 की ओर घटते हैं।', 'ಪ್ರತಿ ಹತ್ತು ಪಟ್ಟು ದುರ್ಬಲೀಕರಣ ಪ್ರಬಲ ಆಮ್ಲದ pH ಅನ್ನು ಒಂದು ಘಟಕ, ದುರ್ಬಲ ಆಮ್ಲದ್ದನ್ನು ಸುಮಾರು ಅರ್ಧ ಘಟಕ ಏರಿಸುತ್ತದೆ; ಕ್ಷಾರಗಳು ಹಾಗೆಯೇ 7 ಕಡೆಗೆ ಇಳಿಯುತ್ತವೆ.'),
        viva=[Q(W('What is the pH of 0.001 M HCl?', '0.001 M HCl का pH क्या है?', '0.001 M HCl ನ pH ಎಷ್ಟು?'), W('3, since [H⁺] = 10⁻³ M.', '3, क्योंकि [H⁺] = 10⁻³ M।', '3, ಏಕೆಂದರೆ [H⁺] = 10⁻³ M.')),
              Q(W('Can an acid be diluted to pH 8?', 'क्या अम्ल को तनु करके pH 8 तक लाया जा सकता है?', 'ಆಮ್ಲವನ್ನು ದುರ್ಬಲಗೊಳಿಸಿ pH 8 ಮಾಡಬಹುದೇ?'), W('No: water itself gives 10⁻⁷ M H⁺, so the pH approaches 7 from below.', 'नहीं: जल स्वयं 10⁻⁷ M H⁺ देता है, इसलिए pH नीचे से 7 के निकट पहुँचता है।', 'ಇಲ್ಲ: ನೀರೇ 10⁻⁷ M H⁺ ನೀಡುತ್ತದೆ; pH ಕೆಳಗಿನಿಂದ 7 ಸಮೀಪಿಸುತ್ತದೆ.')),
              Q(W('Why does the pH of acetic acid change less on dilution?', 'तनुकरण पर ऐसीटिक अम्ल का pH कम क्यों बदलता है?', 'ದುರ್ಬಲೀಕರಣದಲ್ಲಿ ಅಸಿಟಿಕ್ ಆಮ್ಲದ pH ಕಡಿಮೆ ಏಕೆ ಬದಲಾಗುತ್ತದೆ?'), W('Its degree of ionisation increases on dilution, which partly makes up for the lower concentration.', 'तनुकरण पर उसकी आयनन मात्रा बढ़ती है, जो घटी सांद्रता की आंशिक पूर्ति करती है।', 'ದುರ್ಬಲೀಕರಣದಲ್ಲಿ ಅದರ ಅಯಾನೀಕರಣ ಪ್ರಮಾಣ ಹೆಚ್ಚುತ್ತದೆ, ಕಡಿಮೆಯಾದ ಸಾಂದ್ರತೆಯನ್ನು ಭಾಗಶಃ ಸರಿದೂಗಿಸುತ್ತದೆ.'))])

    STUDY = [W('Look at each slide or specimen and switch on the labels to check the parts.', 'हर स्लाइड या नमूना देखें और भाग जाँचने के लिए नामांकन चालू करें।', 'ಪ್ರತಿ ಸ್ಲೈಡ್ ಅಥವಾ ಮಾದರಿ ನೋಡಿ, ಭಾಗಗಳನ್ನು ಪರಿಶೀಲಿಸಲು ಹೆಸರುಗಳನ್ನು ಆನ್ ಮಾಡಿ.'),
             W('Note the identifying features.', 'पहचान के लक्षण लिखें।', 'ಗುರುತಿಸುವ ಲಕ್ಷಣಗಳನ್ನು ಬರೆಯಿರಿ.'),
             W('Draw a neat labelled diagram of each in your record.', 'अपने अभिलेख में प्रत्येक का साफ़ नामांकित चित्र बनाएँ।', 'ನಿಮ್ಮ ದಾಖಲೆಯಲ್ಲಿ ಪ್ರತಿಯೊಂದರ ಅಚ್ಚುಕಟ್ಟಾದ ಹೆಸರಿಸಿದ ಚಿತ್ರ ಬರೆಯಿರಿ.'),
             W('Record each and compare them in order.', 'प्रत्येक दर्ज करें और क्रम से तुलना करें।', 'ಪ್ರತಿಯೊಂದನ್ನೂ ದಾಖಲಿಸಿ ಕ್ರಮವಾಗಿ ಹೋಲಿಸಿ.')]
    PRE = [W('Focus under low power first, then high power.', 'पहले कम आवर्धन पर, फिर अधिक आवर्धन पर फ़ोकस करें।', 'ಮೊದಲು ಕಡಿಮೆ ವರ್ಧನೆ, ನಂತರ ಹೆಚ್ಚಿನ ವರ್ಧನೆಯಲ್ಲಿ ಫೋಕಸ್ ಮಾಡಿ.'), W('Handle slides and specimens by their edges.', 'स्लाइडें और नमूने किनारों से पकड़ें।', 'ಸ್ಲೈಡ್‌ಗಳು ಮತ್ತು ಮಾದರಿಗಳನ್ನು ಅಂಚುಗಳಿಂದ ಹಿಡಿಯಿರಿ.')]

    lab(id='meiosis-stages', bench='specimens', setup={'kit': 'meiosis'}, **bio2,
        keywords=['meiosis', 'cell division', 'bivalent', 'chiasma', 'crossing over', 'tetrad', 'onion bud', 'grasshopper testis', 'reduction division'],
        title=W('Stages of meiosis', 'अर्धसूत्री विभाजन की अवस्थाएँ', 'ಅರೆವಿಭಜನೆಯ ಹಂತಗಳು'),
        summary=W('Study prepared slides of onion bud cells or grasshopper testis and identify the stages of meiosis I and II.', 'प्याज़ की कली या टिड्डे के वृषण की तैयार स्लाइडों से अर्धसूत्री विभाजन I और II की अवस्थाएँ पहचानें।', 'ಈರುಳ್ಳಿ ಮೊಗ್ಗು ಅಥವಾ ಮಿಡತೆಯ ವೃಷಣದ ಸಿದ್ಧ ಸ್ಲೈಡ್‌ಗಳಿಂದ ಅರೆವಿಭಜನೆ I ಮತ್ತು II ರ ಹಂತಗಳನ್ನು ಗುರುತಿಸಿ.'),
        aim=W('To study the stages of meiosis in onion bud cells or grasshopper testis through permanent slides.', 'स्थायी स्लाइडों द्वारा प्याज़ की कली की कोशिकाओं या टिड्डे के वृषण में अर्धसूत्री विभाजन की अवस्थाओं का अध्ययन करना।', 'ಶಾಶ್ವತ ಸ್ಲೈಡ್‌ಗಳ ಮೂಲಕ ಈರುಳ್ಳಿ ಮೊಗ್ಗಿನ ಕೋಶಗಳು ಅಥವಾ ಮಿಡತೆಯ ವೃಷಣದಲ್ಲಿ ಅರೆವಿಭಜನೆಯ ಹಂತಗಳನ್ನು ಅಧ್ಯಯನ ಮಾಡುವುದು.'),
        principle=W('Meiosis halves the chromosome number. In meiosis I homologous chromosomes pair, cross over at chiasmata and separate; in meiosis II the sister chromatids separate, giving four haploid cells.', 'अर्धसूत्री विभाजन गुणसूत्र संख्या आधी करता है। अर्धसूत्री I में समजात गुणसूत्र युग्मित होते हैं, काइज़्मा पर जीन विनिमय करते हैं और अलग होते हैं; अर्धसूत्री II में सिस्टर क्रोमैटिड अलग होकर चार अगुणित कोशिकाएँ बनाते हैं।', 'ಅರೆವಿಭಜನೆ ವರ್ಣತಂತು ಸಂಖ್ಯೆಯನ್ನು ಅರ್ಧಗೊಳಿಸುತ್ತದೆ. ಅರೆವಿಭಜನೆ I ರಲ್ಲಿ ಸಮರೂಪ ವರ್ಣತಂತುಗಳು ಜೋಡಿಯಾಗಿ, ಕಯಾಸ್ಮಾದಲ್ಲಿ ಅಡ್ಡಹಾಯ್ದು ಬೇರ್ಪಡುತ್ತವೆ; II ರಲ್ಲಿ ಸಹೋದರ ಕ್ರೊಮ್ಯಾಟಿಡ್‌ಗಳು ಬೇರ್ಪಟ್ಟು ನಾಲ್ಕು ಏಕಗುಣಿತ ಕೋಶಗಳಾಗುತ್ತವೆ.'),
        apparatus=[W('Compound microscope', 'संयुक्त सूक्ष्मदर्शी', 'ಸಂಯುಕ್ತ ಸೂಕ್ಷ್ಮದರ್ಶಕ'), W('Permanent slides of meiosis', 'अर्धसूत्री विभाजन की स्थायी स्लाइडें', 'ಅರೆವಿಭಜನೆಯ ಶಾಶ್ವತ ಸ್ಲೈಡ್‌ಗಳು'), RECORD],
        steps=STUDY, precautions=PRE,
        conclusion=W('Pairing of homologues, chiasmata and a tetrad of four haploid cells mark meiosis apart from mitosis.', 'समजातों का युग्मन, काइज़्मा और चार अगुणित कोशिकाओं का चतुष्क अर्धसूत्री विभाजन को समसूत्री से अलग करते हैं।', 'ಸಮರೂಪಗಳ ಜೋಡಣೆ, ಕಯಾಸ್ಮಾ ಮತ್ತು ನಾಲ್ಕು ಏಕಗುಣಿತ ಕೋಶಗಳ ಚತುಷ್ಕ ಅರೆವಿಭಜನೆಯನ್ನು ಸಮವಿಭಜನೆಯಿಂದ ಬೇರ್ಪಡಿಸುತ್ತವೆ.'),
        viva=[Q(W('What is a bivalent?', 'द्विसंयोजक क्या है?', 'ದ್ವಿಸಂಯೋಜಕ ಎಂದರೇನು?'), W('A pair of homologous chromosomes held together during prophase I.', 'प्रोफ़ेज़ I में साथ जुड़ा समजात गुणसूत्रों का युग्म।', 'ಪ್ರೊಫೇಸ್ I ರಲ್ಲಿ ಜೊತೆಯಾಗಿರುವ ಸಮರೂಪ ವರ್ಣತಂತುಗಳ ಜೋಡಿ.')),
              Q(W('Where does crossing over happen?', 'जीन विनिमय कहाँ होता है?', 'ಅಡ್ಡಹಾಯುವಿಕೆ ಎಲ್ಲಿ ನಡೆಯುತ್ತದೆ?'), W('Between non-sister chromatids of homologues, in pachytene; chiasmata show where.', 'पैकिटीन में समजातों के असहोदर क्रोमैटिडों के बीच; काइज़्मा स्थान दिखाते हैं।', 'ಪ್ಯಾಕಿಟೀನ್‌ನಲ್ಲಿ ಸಮರೂಪಗಳ ಸಹೋದರವಲ್ಲದ ಕ್ರೊಮ್ಯಾಟಿಡ್‌ಗಳ ನಡುವೆ; ಕಯಾಸ್ಮಾ ಸ್ಥಳ ತೋರಿಸುತ್ತದೆ.')),
              Q(W('Why is meiosis I called reduction division?', 'अर्धसूत्री I को न्यूनकारी विभाजन क्यों कहते हैं?', 'ಅರೆವಿಭಜನೆ I ಅನ್ನು ಅಪಕರ್ಷಣ ವಿಭಜನೆ ಎಂದು ಏಕೆ ಕರೆಯುತ್ತಾರೆ?'), W('Whole homologues separate, so each daughter cell has half the chromosomes.', 'पूरे समजात अलग होते हैं, इसलिए हर संतति कोशिका में आधे गुणसूत्र होते हैं।', 'ಸಂಪೂರ್ಣ ಸಮರೂಪಗಳು ಬೇರ್ಪಡುತ್ತವೆ; ಪ್ರತಿ ಮರಿಕೋಶದಲ್ಲಿ ಅರ್ಧ ವರ್ಣತಂತುಗಳು.'))])

    lab(id='pollination-adaptations', bench='specimens', setup={'kit': 'pollination'}, **bio2,
        keywords=['pollination', 'wind pollination', 'insect pollination', 'bird pollination', 'anemophily', 'entomophily', 'ornithophily', 'maize', 'salvia'],
        title=W('Flowers adapted to pollination', 'परागण के लिए अनुकूलित पुष्प', 'ಪರಾಗಸ್ಪರ್ಶಕ್ಕೆ ಹೊಂದಿಕೊಂಡ ಹೂವುಗಳು'),
        summary=W('Compare flowers pollinated by wind, insects and birds and list their adaptations.', 'वायु, कीट और पक्षी द्वारा परागित पुष्पों की तुलना करें और उनके अनुकूलन लिखें।', 'ಗಾಳಿ, ಕೀಟ ಮತ್ತು ಪಕ್ಷಿಗಳಿಂದ ಪರಾಗಸ್ಪರ್ಶವಾಗುವ ಹೂವುಗಳನ್ನು ಹೋಲಿಸಿ ಅವುಗಳ ಹೊಂದಾಣಿಕೆಗಳನ್ನು ಬರೆಯಿರಿ.'),
        aim=W('To study flowers adapted to pollination by different agencies: wind, insects and birds.', 'विभिन्न कारकों (वायु, कीट, पक्षी) द्वारा परागण के लिए अनुकूलित पुष्पों का अध्ययन करना।', 'ವಿವಿಧ ಕಾರಕಗಳಿಂದ (ಗಾಳಿ, ಕೀಟ, ಪಕ್ಷಿ) ಪರಾಗಸ್ಪರ್ಶಕ್ಕೆ ಹೊಂದಿಕೊಂಡ ಹೂವುಗಳನ್ನು ಅಧ್ಯಯನ ಮಾಡುವುದು.'),
        principle=W('A flower’s form suits its pollinator: wind-pollinated flowers are small and dull with light pollen and feathery stigmas; insect- and bird-pollinated flowers are large or tubular, bright and full of nectar.', 'पुष्प का रूप उसके परागणकर्ता के अनुरूप होता है: वायु-परागित पुष्प छोटे, फीके, हल्के पराग और पंखदार वर्तिकाग्र वाले; कीट- व पक्षी-परागित पुष्प बड़े या नलिकाकार, चमकीले और मकरंद से भरे होते हैं।', 'ಹೂವಿನ ರೂಪ ಅದರ ಪರಾಗಸ್ಪರ್ಶಕಕ್ಕೆ ತಕ್ಕಂತೆ: ಗಾಳಿ ಪರಾಗಿತ ಹೂವುಗಳು ಚಿಕ್ಕ, ಮಂದ, ಹಗುರ ಪರಾಗ ಮತ್ತು ಗರಿಯಂತಹ ಶಲಾಕಾಗ್ರ; ಕೀಟ ಮತ್ತು ಪಕ್ಷಿ ಪರಾಗಿತ ಹೂವುಗಳು ದೊಡ್ಡ ಅಥವಾ ನಳಿಕೆಯಾಕಾರ, ಉಜ್ವಲ, ಮಕರಂದಭರಿತ.'),
        apparatus=[W('Fresh or preserved flowers: maize, Salvia, Bignonia', 'ताज़े या परिरक्षित पुष्प: मक्का, साल्विया, बिग्नोनिया', 'ತಾಜಾ ಅಥವಾ ಸಂರಕ್ಷಿತ ಹೂವುಗಳು: ಮೆಕ್ಕೆಜೋಳ, ಸಾಲ್ವಿಯಾ, ಬಿಗ್ನೋನಿಯಾ'), W('Hand lens and forceps', 'हस्त लेंस और चिमटी', 'ಕೈ ಮಸೂರ ಮತ್ತು ಚಿಮುಟ'), RECORD],
        steps=STUDY, precautions=PRE,
        conclusion=W('Colour, scent, nectar, the size of pollen and the form of stigma all match the pollinating agent.', 'रंग, गंध, मकरंद, पराग का आकार और वर्तिकाग्र का रूप सब परागण कारक से मेल खाते हैं।', 'ಬಣ್ಣ, ವಾಸನೆ, ಮಕರಂದ, ಪರಾಗದ ಗಾತ್ರ ಮತ್ತು ಶಲಾಕಾಗ್ರದ ರೂಪ ಎಲ್ಲವೂ ಪರಾಗಸ್ಪರ್ಶ ಕಾರಕಕ್ಕೆ ಹೊಂದುತ್ತವೆ.'),
        viva=[Q(W('Why do wind-pollinated flowers make so much pollen?', 'वायु-परागित पुष्प इतना पराग क्यों बनाते हैं?', 'ಗಾಳಿ ಪರಾಗಿತ ಹೂವುಗಳು ಏಕೆ ಇಷ್ಟು ಪರಾಗ ಉತ್ಪಾದಿಸುತ್ತವೆ?'), W('Wind carries pollen at random, so most of it is wasted.', 'वायु पराग को यादृच्छिक ले जाती है, इसलिए अधिकांश व्यर्थ जाता है।', 'ಗಾಳಿ ಪರಾಗವನ್ನು ಯಾದೃಚ್ಛಿಕವಾಗಿ ಒಯ್ಯುತ್ತದೆ; ಹೆಚ್ಚಿನದು ವ್ಯರ್ಥವಾಗುತ್ತದೆ.')),
              Q(W('How does Salvia’s stamen work?', 'साल्विया का पुंकेसर कैसे काम करता है?', 'ಸಾಲ್ವಿಯಾದ ಕೇಸರ ಹೇಗೆ ಕೆಲಸ ಮಾಡುತ್ತದೆ?'), W('As a lever: the entering bee pushes one end and the anther swings down onto its back.', 'उत्तोलक की तरह: अंदर जाती मधुमक्खी एक सिरा धकेलती है और परागकोश उसकी पीठ पर झुक जाता है।', 'ಸನ್ನೆಯಂತೆ: ಒಳ ನುಗ್ಗುವ ಜೇನುನೊಣ ಒಂದು ತುದಿ ತಳ್ಳುತ್ತದೆ, ಪರಾಗಕೋಶ ಅದರ ಬೆನ್ನಿಗೆ ಬಾಗುತ್ತದೆ.')),
              Q(W('Why do bird-pollinated flowers often lack scent?', 'पक्षी-परागित पुष्पों में प्रायः गंध क्यों नहीं होती?', 'ಪಕ್ಷಿ ಪರಾಗಿತ ಹೂವುಗಳಿಗೆ ಹೆಚ್ಚಾಗಿ ವಾಸನೆ ಏಕೆ ಇರುವುದಿಲ್ಲ?'), W('Birds find flowers by sight, not smell.', 'पक्षी पुष्पों को गंध से नहीं, दृष्टि से खोजते हैं।', 'ಪಕ್ಷಿಗಳು ಹೂವುಗಳನ್ನು ವಾಸನೆಯಿಂದಲ್ಲ, ದೃಷ್ಟಿಯಿಂದ ಹುಡುಕುತ್ತವೆ.'))])

    lab(id='dna-isolation', bench='dna-isolation', **bio2,
        keywords=['dna isolation', 'dna extraction', 'biotechnology', 'molecular basis of inheritance', 'spinach', 'green peas', 'papaya', 'ethanol', 'protease'],
        title=W('Isolation of DNA from plant material', 'पादप पदार्थ से DNA का पृथक्करण', 'ಸಸ್ಯ ವಸ್ತುವಿನಿಂದ DNA ಪ್ರತ್ಯೇಕೀಕರಣ'),
        summary=W('Grind, filter, digest and add cold ethanol to spool DNA from peas, spinach or papaya, and compare the yields.', 'मटर, पालक या पपीते से पीसकर, छानकर, पचाकर और ठंडा एथेनॉल डालकर DNA लपेटें और उपज की तुलना करें।', 'ಬಟಾಣಿ, ಪಾಲಕ್ ಅಥವಾ ಪಪ್ಪಾಯಿಯಿಂದ ಅರೆದು, ಸೋಸಿ, ಜೀರ್ಣಿಸಿ, ತಣ್ಣನೆಯ ಎಥನಾಲ್ ಸೇರಿಸಿ DNA ಸುತ್ತಿ ಇಳುವರಿ ಹೋಲಿಸಿ.'),
        aim=W('To isolate DNA from available plant material such as green pea seeds, spinach or papaya.', 'हरी मटर, पालक या पपीते जैसे उपलब्ध पादप पदार्थ से DNA पृथक करना।', 'ಹಸಿರು ಬಟಾಣಿ, ಪಾಲಕ್ ಅಥವಾ ಪಪ್ಪಾಯಿಯಂತಹ ಲಭ್ಯ ಸಸ್ಯ ವಸ್ತುವಿನಿಂದ DNA ಪ್ರತ್ಯೇಕಿಸುವುದು.'),
        principle=W('Detergent dissolves the cell and nuclear membranes; salt keeps DNA in solution; protease removes the histone proteins. DNA is insoluble in cold ethanol, so it comes out as white threads at the boundary.', 'अपमार्जक कोशिका व केंद्रक झिल्ली घोलता है; लवण DNA को विलयन में रखता है; प्रोटिएज़ हिस्टोन प्रोटीन हटाता है। DNA ठंडे एथेनॉल में अघुलनशील है, इसलिए सीमा पर सफ़ेद धागों के रूप में निकलता है।', 'ಮಾರ್ಜಕ ಕೋಶ ಮತ್ತು ಕೋಶಕೇಂದ್ರ ಪೊರೆ ಕರಗಿಸುತ್ತದೆ; ಉಪ್ಪು DNA ಅನ್ನು ದ್ರಾವಣದಲ್ಲಿ ಇಡುತ್ತದೆ; ಪ್ರೋಟಿಯೇಸ್ ಹಿಸ್ಟೋನ್ ಪ್ರೋಟೀನ್ ತೆಗೆಯುತ್ತದೆ. DNA ತಣ್ಣನೆಯ ಎಥನಾಲ್‌ನಲ್ಲಿ ಕರಗದು; ಗಡಿಯಲ್ಲಿ ಬಿಳಿ ಎಳೆಗಳಾಗಿ ಹೊರಬರುತ್ತದೆ.'),
        apparatus=[W('Mortar and pestle', 'खरल और मूसल', 'ಒರಳು ಮತ್ತು ಒನಕೆ'), W('Salt, liquid detergent and protease (pineapple juice)', 'नमक, तरल अपमार्जक और प्रोटिएज़ (अनानास रस)', 'ಉಪ್ಪು, ದ್ರವ ಮಾರ್ಜಕ ಮತ್ತು ಪ್ರೋಟಿಯೇಸ್ (ಅನಾನಸ್ ರಸ)'), W('Muslin cloth, funnel and boiling tube', 'मलमल का कपड़ा, कीप और क्वथन नली', 'ಮಸ್ಲಿನ್ ಬಟ್ಟೆ, ಆಲಿಕೆ ಮತ್ತು ಕುದಿಸುವ ನಳಿಕೆ'), W('Ice-cold ethanol and a glass rod', 'बर्फ़-ठंडा एथेनॉल और काँच की छड़', 'ಮಂಜುಗಡ್ಡೆಯಷ್ಟು ತಣ್ಣನೆಯ ಎಥನಾಲ್ ಮತ್ತು ಗಾಜಿನ ಸರಳು')],
        steps=[W('Weigh the tissue and grind it with salt and detergent solution.', 'ऊतक तौलें और उसे नमक व अपमार्जक विलयन के साथ पीसें।', 'ಅಂಗಾಂಶ ತೂಗಿ ಉಪ್ಪು ಮತ್ತು ಮಾರ್ಜಕ ದ್ರಾವಣದೊಂದಿಗೆ ಅರೆಯಿರಿ.'),
               W('Filter through muslin into a boiling tube.', 'मलमल से क्वथन नली में छानें।', 'ಮಸ್ಲಿನ್ ಮೂಲಕ ಕುದಿಸುವ ನಳಿಕೆಗೆ ಸೋಸಿ.'),
               W('Add a few drops of protease, then RNase, and wait a few minutes.', 'प्रोटिएज़ की कुछ बूँदें, फिर RNase डालें और कुछ मिनट रुकें।', 'ಕೆಲವು ಹನಿ ಪ್ರೋಟಿಯೇಸ್, ನಂತರ RNase ಸೇರಿಸಿ ಕೆಲವು ನಿಮಿಷ ಕಾಯಿರಿ.'),
               W('Pour ice-cold ethanol gently down the side to form a layer.', 'बर्फ़-ठंडा एथेनॉल धीरे से दीवार के सहारे डालें ताकि परत बने।', 'ತಣ್ಣನೆಯ ಎಥನಾಲ್ ಅನ್ನು ಗೋಡೆಯಗುಂಟ ನಿಧಾನವಾಗಿ ಸುರಿದು ಪದರ ಮಾಡಿ.'),
               W('Spool the white threads on a glass rod, weigh them and repeat with other masses and tissues.', 'सफ़ेद धागे काँच की छड़ पर लपेटें, तौलें और अन्य द्रव्यमानों व ऊतकों से दोहराएँ।', 'ಬಿಳಿ ಎಳೆಗಳನ್ನು ಗಾಜಿನ ಸರಳಿಗೆ ಸುತ್ತಿ, ತೂಗಿ, ಇತರ ದ್ರವ್ಯರಾಶಿ ಮತ್ತು ಅಂಗಾಂಶಗಳೊಂದಿಗೆ ಪುನರಾವರ್ತಿಸಿ.')],
        precautions=[W('Keep the ethanol in ice until it is used.', 'उपयोग तक एथेनॉल को बर्फ़ में रखें।', 'ಬಳಸುವವರೆಗೆ ಎಥನಾಲ್ ಅನ್ನು ಮಂಜುಗಡ್ಡೆಯಲ್ಲಿಡಿ.'), W('Do not shake the tube after adding ethanol; the threads break.', 'एथेनॉल डालने के बाद नली न हिलाएँ; धागे टूट जाते हैं।', 'ಎಥನಾಲ್ ಸೇರಿಸಿದ ನಂತರ ನಳಿಕೆ ಅಲುಗಿಸಬೇಡಿ; ಎಳೆಗಳು ಮುರಿಯುತ್ತವೆ.'), W('Ethanol is flammable: keep it away from flames.', 'एथेनॉल ज्वलनशील है: उसे लौ से दूर रखें।', 'ಎಥನಾಲ್ ದಹನಶೀಲ: ಜ್ವಾಲೆಯಿಂದ ದೂರವಿಡಿ.')],
        conclusion=W('DNA separates as white threads in cold ethanol; the amount spooled rises in proportion to the tissue used.', 'ठंडे एथेनॉल में DNA सफ़ेद धागों के रूप में अलग होता है; लपेटी गई मात्रा प्रयुक्त ऊतक के अनुपात में बढ़ती है।', 'ತಣ್ಣನೆಯ ಎಥನಾಲ್‌ನಲ್ಲಿ DNA ಬಿಳಿ ಎಳೆಗಳಾಗಿ ಬೇರ್ಪಡುತ್ತದೆ; ಸುತ್ತಿದ ಪ್ರಮಾಣ ಬಳಸಿದ ಅಂಗಾಂಶಕ್ಕೆ ಅನುಪಾತದಲ್ಲಿ ಹೆಚ್ಚುತ್ತದೆ.'),
        viva=[Q(W('Why is detergent added?', 'अपमार्जक क्यों मिलाया जाता है?', 'ಮಾರ್ಜಕ ಏಕೆ ಸೇರಿಸಲಾಗುತ್ತದೆ?'), W('To break the lipid membranes of the cell and the nucleus.', 'कोशिका और केंद्रक की लिपिड झिल्लियाँ तोड़ने के लिए।', 'ಕೋಶ ಮತ್ತು ಕೋಶಕೇಂದ್ರದ ಲಿಪಿಡ್ ಪೊರೆಗಳನ್ನು ಒಡೆಯಲು.')),
              Q(W('Why must the ethanol be cold?', 'एथेनॉल ठंडा क्यों होना चाहिए?', 'ಎಥನಾಲ್ ಏಕೆ ತಣ್ಣಗಿರಬೇಕು?'), W('DNA is less soluble at low temperature, so more of it precipitates.', 'कम ताप पर DNA कम घुलता है, इसलिए अधिक अवक्षेपित होता है।', 'ಕಡಿಮೆ ತಾಪದಲ್ಲಿ DNA ಕಡಿಮೆ ಕರಗುತ್ತದೆ; ಹೆಚ್ಚು ಅವಕ್ಷೇಪಿಸುತ್ತದೆ.')),
              Q(W('What does the protease remove?', 'प्रोटिएज़ क्या हटाता है?', 'ಪ್ರೋಟಿಯೇಸ್ ಏನನ್ನು ತೆಗೆಯುತ್ತದೆ?'), W('The histone proteins round which DNA is wound.', 'हिस्टोन प्रोटीन, जिन पर DNA लिपटा होता है।', 'DNA ಸುತ್ತಿಕೊಂಡಿರುವ ಹಿಸ್ಟೋನ್ ಪ್ರೋಟೀನ್‌ಗಳು.'))])
